// Checked-in synthetic bytes generated by tool/RecordBatchOracle.java using
// separately installed official Kafka 4.0.2 APIs. No Java or broker is required.
import 'dart:convert';
import 'dart:io';

import 'package:kafka_client/src/codec/record_batch.dart';
import 'package:test/test.dart';

Map<String, Object?> _record(KafkaRecord record) => {
      'offset': record.offset.toString(),
      'timestamp': record.timestamp.toString(),
      'key': record.key == null ? null : base64Encode(record.key!),
      'value': record.value == null ? null : base64Encode(record.value!),
      'headers': [
        for (final header in record.headers)
          [
            base64Encode(utf8.encode(header.key)),
            header.value == null ? null : base64Encode(header.value!),
          ]
      ],
    };

void main() {
  final artifact = jsonDecode(
          File('test/fixtures/record_batch_java_4_0_2.json').readAsStringSync())
      as Map<String, dynamic>;
  final cases = artifact['cases'] as List<dynamic>;
  test('Java oracle provenance and complete named case set', () {
    expect(artifact['formatVersion'], 1);
    expect(artifact['oracle']['kafkaVersion'], '4.0.2');
    expect(artifact['oracle']['generator'], 'tool/RecordBatchOracle.java');
    expect(artifact['oracle']['jarsSha256']['kafka-clients-4.0.2.jar'],
        '90ef3a38696ee29e4f8dec2b2910bd31d8da0e69cb53a62a231a7d05fea32ad9');
    expect(cases.map((entry) => entry['name']), [
      'create-time-binary-headers-negative-delta',
      'log-append-time',
      'compacted-sparse-prefix-tail',
      'delete-horizon-sparse',
      'compacted-empty',
      'commit-control',
      'abort-control',
      'transactional-visible-read-uncommitted',
      'above-js-safe-integer',
      'no-timestamp-sentinel',
    ]);
  });
  for (final entry in cases.cast<Map<String, dynamic>>()) {
    test('official Kafka 4.0.2 batch: ${entry['name']}', () {
      final bytes = base64Decode(entry['wire'] as String);
      final decoded = decodeRecordBatchesWithProgress(bytes);
      expect(decoded.lastBatchOffset.toString(), entry['lastBatchOffset']);
      expect(decoded.records.map(_record).toList(), entry['records']);
      expect(
          decodeRecordBatches(bytes).map(_record).toList(), entry['records']);
      final fetch = decodeFetchRecordBatchesWithProgress(bytes);
      expect(fetch.lastBatchOffset.toString(), entry['lastBatchOffset']);
      expect(fetch.records.map(_record).toList(), entry['records']);
    });
  }
}
